var RD_PALETTE = ['#5E6AD2','#22D3EE','#F5A623','#10B981','#A78BFA','#EF4444'];

function parseData(text){
  var lines = String(text == null ? '' : text).split(/\r?\n/);
  var axes = null, series = [], errors = [];
  for (var i = 0; i < lines.length; i++){
    var l = lines[i].trim();
    if (!l || l.charAt(0) === '#') continue;
    var idx = l.indexOf(':');
    if (idx < 0) idx = l.indexOf('：');
    if (idx < 0){ errors.push({ line:i + 1, text:l, why:'缺少冒号分隔的名称' }); continue; }
    var key = l.slice(0, idx).trim();
    var rest = l.slice(idx + 1).trim();
    var parts = rest.split(/[,，]/).map(function(x){ return x.trim(); }).filter(function(x){ return x !== ''; });
    if (key === '轴' || key.toLowerCase() === 'axes'){
      if (!parts.length){ errors.push({ line:i + 1, text:l, why:'轴名列表为空' }); continue; }
      axes = parts;
      continue;
    }
    if (!parts.length){ errors.push({ line:i + 1, text:l, why:'没有数值' }); continue; }
    var vals = [], badv = false;
    for (var j = 0; j < parts.length; j++){
      var v = parseFloat(parts[j]);
      if (!isFinite(v)){ badv = true; break; }
      vals.push(v);
    }
    if (badv){ errors.push({ line:i + 1, text:l, why:'包含非数值' }); continue; }
    series.push({ name:key, values:vals });
  }
  var width = 0;
  for (var s = 0; s < series.length; s++) width = Math.max(width, series[s].values.length);
  if (!axes){
    axes = [];
    for (var a = 0; a < width; a++) axes.push('指标' + (a + 1));
  }
  for (var k = 0; k < series.length; k++){
    while (series[k].values.length < axes.length) series[k].values.push(0);
    if (series[k].values.length > axes.length){
      errors.push({ line:0, text:series[k].name, why:'数值个数超过轴数，多余部分已截断' });
      series[k].values = series[k].values.slice(0, axes.length);
    }
  }
  return { axes:axes, series:series, errors:errors };
}

function maxValue(series, floor){
  var mx = floor || 0;
  for (var i = 0; i < series.length; i++)
    for (var j = 0; j < series[i].values.length; j++) mx = Math.max(mx, series[i].values[j]);
  return mx > 0 ? mx : 1;
}

function axisAngle(index, count){
  return -Math.PI / 2 + (Math.PI * 2 * index) / (count || 1);
}

function polarPoint(cx, cy, r, angle){
  return { x: cx + r * Math.cos(angle), y: cy + r * Math.sin(angle) };
}

function polygonPoints(values, opt){
  opt = opt || {};
  var cx = opt.cx || 0, cy = opt.cy || 0, R = opt.r || 100, mx = opt.max || 1;
  var pts = [];
  for (var i = 0; i < values.length; i++){
    var ratio = Math.max(0, Math.min(1, values[i] / mx));
    var p = polarPoint(cx, cy, R * ratio, axisAngle(i, values.length));
    pts.push({ x: Math.round(p.x * 100) / 100, y: Math.round(p.y * 100) / 100, value: values[i] });
  }
  return pts;
}

function polygonArea(pts){
  if (pts.length < 3) return 0;
  var s = 0;
  for (var i = 0; i < pts.length; i++){
    var a = pts[i], b = pts[(i + 1) % pts.length];
    s += a.x * b.y - b.x * a.y;
  }
  return Math.round(Math.abs(s) / 2 * 100) / 100;
}

function seriesStats(s, axes){
  var v = s.values, n = v.length;
  if (!n) return { name:s.name, mean:0, min:0, max:0, cv:0, balance:0, strongest:'', weakest:'', sum:0 };
  var sum = 0, mn = Infinity, mx = -Infinity, mnI = 0, mxI = 0;
  for (var i = 0; i < n; i++){
    sum += v[i];
    if (v[i] < mn){ mn = v[i]; mnI = i; }
    if (v[i] > mx){ mx = v[i]; mxI = i; }
  }
  var mean = sum / n, varsum = 0;
  for (var j = 0; j < n; j++) varsum += (v[j] - mean) * (v[j] - mean);
  var sd = Math.sqrt(varsum / n);
  var cv = mean !== 0 ? sd / mean : 0;
  return {
    name: s.name, sum: round2(sum), mean: round2(mean), min: mn, max: mx, sd: round2(sd),
    cv: round2(cv), balance: Math.max(0, Math.round((1 - cv) * 1000) / 10),
    strongest: axes[mxI] || '', weakest: axes[mnI] || ''
  };
}

function round2(n){ return Math.round(n * 100) / 100; }

function compare(data){
  var out = [];
  for (var a = 0; a < data.axes.length; a++){
    var row = { axis: data.axes[a], values: [], best: '', worst: '', spread: 0 };
    var best = -Infinity, worst = Infinity;
    for (var s = 0; s < data.series.length; s++){
      var v = data.series[s].values[a];
      row.values.push({ name: data.series[s].name, value: v });
      if (v > best){ best = v; row.best = data.series[s].name; }
      if (v < worst){ worst = v; row.worst = data.series[s].name; }
    }
    row.spread = data.series.length > 1 ? round2(best - worst) : 0;
    out.push(row);
  }
  return out;
}

function layout(data, opt){
  opt = opt || {};
  var size = opt.size || 340, pad = opt.pad || 52;
  var cx = size / 2, cy = size / 2, R = size / 2 - pad;
  if (!data.axes.length || !data.series.length) return { empty:true, size:size, cx:cx, cy:cy, r:R, rings:[], axes:[], shapes:[] };
  var mx = opt.max || maxValue(data.series, 0);
  var ringCount = opt.rings || 4, rings = [];
  for (var i = 1; i <= ringCount; i++) rings.push({ r: R * i / ringCount, value: round2(mx * i / ringCount) });
  var axes = [];
  for (var a = 0; a < data.axes.length; a++){
    var ang = axisAngle(a, data.axes.length);
    var end = polarPoint(cx, cy, R, ang);
    var lab = polarPoint(cx, cy, R + 18, ang);
    axes.push({ name: data.axes[a], x: round2(end.x), y: round2(end.y), lx: round2(lab.x), ly: round2(lab.y),
                anchor: Math.abs(Math.cos(ang)) < 0.2 ? 'middle' : (Math.cos(ang) > 0 ? 'start' : 'end') });
  }
  var shapes = [];
  for (var s = 0; s < data.series.length; s++){
    var pts = polygonPoints(data.series[s].values, { cx:cx, cy:cy, r:R, max:mx });
    shapes.push({ name: data.series[s].name, points: pts, color: RD_PALETTE[s % RD_PALETTE.length],
                  area: polygonArea(pts), coverage: Math.round(polygonArea(pts) / polygonArea(polygonPoints(data.axes.map(function(){ return mx; }), { cx:cx, cy:cy, r:R, max:mx })) * 1000) / 10 });
  }
  return { empty:false, size:size, cx:cx, cy:cy, r:R, max:mx, rings:rings, axes:axes, shapes:shapes };
}

function escXml(s){
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function toSvg(lay){
  var size = (lay && lay.size) || 340;
  if (!lay || lay.empty) return '<svg xmlns="http://www.w3.org/2000/svg" width="' + size + '" height="' + size + '"></svg>';
  var out = ['<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ' + size + ' ' + size + '" width="100%" height="' + size + '" role="img" aria-label="雷达图">'];
  out.push('<rect width="' + size + '" height="' + size + '" fill="#0A0A0B"/>');
  for (var i = 0; i < lay.rings.length; i++){
    var pts = polygonPoints(lay.axes.map(function(){ return 1; }), { cx:lay.cx, cy:lay.cy, r:lay.rings[i].r, max:1 });
    out.push('<polygon points="' + pts.map(function(p){ return p.x + ',' + p.y; }).join(' ') + '" fill="none" stroke="rgba(255,255,255,.10)"/>');
  }
  for (var a = 0; a < lay.axes.length; a++){
    var ax = lay.axes[a];
    out.push('<line x1="' + lay.cx + '" y1="' + lay.cy + '" x2="' + ax.x + '" y2="' + ax.y + '" stroke="rgba(255,255,255,.14)"/>');
    out.push('<text x="' + ax.lx + '" y="' + (ax.ly + 4) + '" fill="#A1A1AA" font-size="11" text-anchor="' + ax.anchor + '" font-family="system-ui,sans-serif">' + escXml(ax.name) + '</text>');
  }
  for (var s = 0; s < lay.shapes.length; s++){
    var sh = lay.shapes[s];
    out.push('<polygon points="' + sh.points.map(function(p){ return p.x + ',' + p.y; }).join(' ') + '" fill="' + sh.color + '" fill-opacity="0.18" stroke="' + sh.color + '" stroke-width="1.6"><title>' + escXml(sh.name) + '</title></polygon>');
    for (var q = 0; q < sh.points.length; q++){
      out.push('<circle cx="' + sh.points[q].x + '" cy="' + sh.points[q].y + '" r="2.6" fill="' + sh.color + '"/>');
    }
  }
  out.push('</svg>');
  return out.join('');
}

var RadarForgePure = {
  parseData: parseData, maxValue: maxValue, axisAngle: axisAngle, polarPoint: polarPoint,
  polygonPoints: polygonPoints, polygonArea: polygonArea, seriesStats: seriesStats,
  compare: compare, layout: layout, toSvg: toSvg, PALETTE: RD_PALETTE
};
if (typeof module !== 'undefined' && module.exports) module.exports = RadarForgePure;
if (typeof window !== 'undefined') window.RadarForgePure = RadarForgePure;
